# ------------------------------------------------------------- data files
_DATA_DIR = _os.path.join(_HERE, "data")


def _data(name):
    """A data/*.yaml file as a dict; a missing file reads as empty."""
    try:
        with open(_os.path.join(_DATA_DIR, name), encoding="utf-8") as fh:
            return _yaml.safe_load(fh) or {}
    except FileNotFoundError:
        return {}


def _authors(entries):
    """data/authors.yaml as (slug -> name, slug -> profile URL). Entries
    without a name or url are left out of that map."""
    names, links = {}, {}
    for slug, entry in entries.items():
        entry = entry or {}
        if entry.get("name"):
            names[slug] = entry["name"]
        if entry.get("url"):
            links[slug] = entry["url"]
    return names, links


# Tags and bylines reach Pelican as slugs, so their URLs are exact; the
# site plugin sets each Tag and Author object's display name from these
# maps. AUTHOR_LINKS is the Person's sameAs in the structured data.
TAG_DISPLAY = _data("tags.yaml")
AUTHOR_DISPLAY, AUTHOR_LINKS = _authors(_data("authors.yaml"))

FEED_ALL_ATOM = "feeds/all.atom.xml"
